// HISTORY IMPORT (chạy tay, 1 lần lúc go-live) — kéo lại TOÀN BỘ 60 ngày, ĐỦ 8 stream, 3 shop.
// Vận hành hằng ngày KHÔNG dùng file này: `pancake-sync-30m` (30') + `pancake-nightly` (3h sáng).
// Land TEXT THÔ vào Bronze (KHÔNG để n8n parse JSON). SỬA khối CONFIG rồi Execute.
// THỨ TỰ STREAM CỐ Ý: products (+ products/variations) TRƯỚC orders — order cần Variant.costPrice để tính COGS.
/**
 * Khoá lấy từ node "Lấy khoá từ bảng Setting" (mỗi dòng = 1 cặp key/value của bảng `app."Setting"`).
 * Để khoá trong bảng thay vì viết thẳng vào đây: mở bảng là xem được, đổi khoá chỉ sửa 1 ô, và
 * file workflow trong repo khớp tuyệt đối bản đang chạy nên diff được.
 */
const KHOA = Object.fromEntries($input.all().map((i) => [i.json.key, i.json.value]));
const KHOA_THIEU = ["n8nAppUrl","n8nIngestSecret","pancakeApiKeyKho","pancakeApiKeyShopee","pancakeApiKeyTiktok","pancakeShopIdKho","pancakeShopIdShopee","pancakeShopIdTiktok"].filter((k) => !KHOA[k]);
if (KHOA_THIEU.length) {
  throw new Error(
    `THIẾU KHOÁ trong bảng app."Setting": ${KHOA_THIEU.join(", ")}. Thêm dòng key/value tương ứng rồi ` +
      `chạy lại — không cần đụng file cấu hình hay dựng lại container.`
  );
}

const CONFIG = {
  base: "https://pos.pages.fm/api/v1",
  appUrl: KHOA.n8nAppUrl,              // go-live: http://hogikids-app:3000 | test: http://<IP-Tailscale-dev>:3000
  ingestSecret: KHOA.n8nIngestSecret,  // == INGEST_SECRET trong .env app
  // Shop ID đọc từ bảng Setting (clone-and-go 2026-08-21) — cùng nguồn với app; bản clone điền id CỦA HỌ ở /cai-dat.
  shops: {
    kho:    { id: KHOA.pancakeShopIdKho,    key: KHOA.pancakeApiKeyKho },
    shopee: { id: KHOA.pancakeShopIdShopee, key: KHOA.pancakeApiKeyShopee },
    tiktok: { id: KHOA.pancakeShopIdTiktok, key: KHOA.pancakeApiKeyTiktok },
  },
};

// THỨ TỰ MẢNG QUAN TRỌNG: products/products-variations đứng TRƯỚC orders (COGS).
// `shops` = shop THẬT SỰ có dữ liệu cho stream đó (Task 0 discovery) — purchases chỉ có ở shop kho;
// transactions + reverse_order chỉ có ở 2 shop marketplace (Shopee/TikTok).
const STREAMS = [
  { name: "products",                  shops: ["kho", "shopee", "tiktok"] },
  { name: "products/variations",       shops: ["kho", "shopee", "tiktok"] },
  { name: "orders",                    shops: ["kho", "shopee", "tiktok"], dated: true },
  { name: "purchases",                 shops: ["kho"] },
  { name: "inventory_histories",       shops: ["kho", "shopee", "tiktok"] },
  { name: "transactions",              shops: ["shopee", "tiktok"] },
  { name: "marketplace/reverse_order", shops: ["shopee", "tiktok"] },
  { name: "customers",                 shops: ["kho", "shopee", "tiktok"] },
];

const http = this.helpers.httpRequest;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const nowSec = Math.floor(Date.now() / 1000);
// Pancake POS shop chỉ dùng từ ĐẦU 2026 (chủ shop xác nhận) — kéo xa hơn cũng không có dữ liệu.
// Mốc CỐ ĐỊNH (không phải 'N ngày trước'): chạy lại tháng sau vẫn phủ đúng từ đầu năm.
const sinceSec = Math.floor(new Date("2026-01-01T00:00:00+07:00").getTime() / 1000);
// 7 ngày/cửa sổ (không phải 1): ~195 ngày × 3 shop, để 1 ngày/cửa sổ là ~600 request — Pancake
// đã tạm chặn key+IP vì bắn quá nhiều (13/07). Phân trang vẫn lấy hết đơn trong mỗi cửa sổ.
const SPLIT_DAYS = 7;

/** Cửa sổ ngày [sinceSec, nowSec) chia theo SPLIT_DAYS. Cửa sổ < 1 ngày → đúng 1 lát. */
function buildDateWindows() {
  const windows = [];
  for (let start = sinceSec; start < nowSec; start += SPLIT_DAYS * 86400) {
    windows.push({ start, end: Math.min(start + SPLIT_DAYS * 86400, nowSec) });
  }
  return windows.length ? windows : [{ start: sinceSec, end: nowSec }];
}

/** Rút total_pages bằng regex trên TEXT THÔ — TUYỆT ĐỐI KHÔNG JSON.parse (int64 sẽ hỏng). */
function totalPagesOf(text) {
  const m = text.match(/"total_pages":\s*(\d+)/);
  return m ? Number(m[1]) : 1;
}

const results = [];
const errors = [];
// Shop bị Pancake TỪ CHỐI XÁC THỰC (401/403) — không đụng tới nữa trong lượt chạy này.
const authDeadShops = new Set();

/** 401/403 = key sai/bị chặn. KHÁC hẳn lỗi mạng/rate-limit: thử lại chỉ làm tình hình tệ hơn. */
function isAuthError(err) {
  const code = (err && (err.httpCode || err.statusCode || (err.response && err.response.status))) || "";
  const msg = (err && err.message) || String(err);
  return String(code) === "401" || String(code) === "403" || /status code (401|403)/.test(msg);
}

/** GET 1 trang (TEXT thô) → POST thẳng sang app. Trả total_pages đọc được từ chuỗi thô. */
async function fetchAndLand(streamName, shopKey, win, page) {
  const shop = CONFIG.shops[shopKey];
  // Pancake KHÔNG nhất quán tham số phân trang: đa số stream nghe `page_number`, riêng
  // `inventory_histories` CHỈ nghe `page` — gửi page_number cho nó thì mọi trang đều trả về
  // trang 1 (mất sạch trang 2..N mà không hề báo lỗi). Gửi CẢ HAI, cùng giá trị.
  const qs = { api_key: shop.key, page_number: page, page: page, page_size: 100 };
  if (win) { qs.startDateTime = win.start; qs.endDateTime = win.end; }
  // `encoding: "text"` LÀ BẮT BUỘC: trong n8n `json: false` CHỈ đổi header Accept — responseType của
  // axios chỉ được set từ `encoding`. Thiếu nó, axios VẪN JSON.parse body ⇒ int64 bị làm tròn (hỏng
  // khoá), regex total_pages trượt (chỉ kéo trang 1), và payload thành object ⇒ app trả 400.
  const text = await http({
    method: "GET",
    url: `${CONFIG.base}/shops/${shop.id}/${streamName}`,
    qs,
    json: false,
    encoding: "text",
  });
  // Chốt chặn: bản n8n nào đổi hành vi thì workflow KÊU TO, không âm thầm hỏng khoá.
  if (typeof text !== "string") {
    throw new Error("n8n trả về object, không phải TEXT thô — thiếu encoding:'text'. int64 sẽ hỏng.");
  }
  const totalPages = totalPagesOf(text);

  // Gửi NGUYÊN chuỗi thô sang app — app tự bung mảng/băm/dedupe, KHÔNG parse ở đây.
  const r = await http({
    method: "POST",
    url: `${CONFIG.appUrl}/api/ingest/raw`,
    json: true,
    headers: { Authorization: `Bearer ${CONFIG.ingestSecret}` },
    body: { stream: streamName, shopId: shop.id, payload: text },
  });
  results.push({
    stream: streamName, shop: shopKey, page, totalPages,
    landed: r && r.stats ? r.stats.landed : undefined,
  });
  return totalPages;
}

/** Kéo 1 stream cho 1 shop — hết mọi trang (và mọi cửa sổ ngày nếu `dated`). */
async function pullStreamShop(streamName, shopKey, dated) {
  // CẦU DAO: key của shop này đã bị từ chối xác thực ⇒ DỪNG HẲN shop đó.
  // Không có cầu dao thì 1 key sai sẽ đẻ ra ~120 request hỏng (60 cửa sổ ngày × 2 lần thử)
  // ⇒ Pancake coi là lạm dụng và chặn tạm key + IP vài giờ (đã xảy ra thật 2026-07-13).
  if (authDeadShops.has(shopKey)) {
    errors.push({
      scope: "SHOP_CHET_XAC_THUC",
      stream: streamName, shop: shopKey, page: 0, window: null,
      message: `BỎ QUA — shop "${shopKey}" đã bị Pancake từ chối xác thực (401/403). Kiểm tra lại api_key.`,
    });
    return;
  }

  const windows = dated ? buildDateWindows() : [null];

  for (const win of windows) {
    let page = 1;
    let totalPages = 1;
    do {
      try {
        totalPages = await fetchAndLand(streamName, shopKey, win, page);
      } catch (err) {
        if (page === 1) {
          // Trang 1 hỏng ⇒ totalPages vẫn = 1 ⇒ do-while thoát ⇒ MẤT CẢ stream/shop này, không chỉ 1 trang.
          // Thử lại ĐÚNG 1 lần sau 2s; vẫn hỏng thì ghi lỗi RÕ RÀNG (scope CA_STREAM_BI_BO) rồi đi tiếp.
          await sleep(2000);
          try {
            totalPages = await fetchAndLand(streamName, shopKey, win, page);
          } catch (err2) {
            const bo = win ? "CẢ CỬA SỔ NGÀY NÀY" : "CẢ STREAM";
            errors.push({
              scope: win ? "CA_CUA_SO_NGAY_BI_BO" : "CA_STREAM_BI_BO",
              stream: streamName, shop: shopKey, page, window: win || null,
              message: `BỎ QUA ${bo} — stream "${streamName}", shop "${shopKey}", trang 1 lỗi 2 lần: ${(err2 && err2.message) || String(err2)}`,
            });
            // Sai key thì mọi cửa sổ/stream sau của shop này cũng sai — ngắt ngay, đừng bắn thêm.
            if (isAuthError(err2)) {
              authDeadShops.add(shopKey);
              return;
            }
          }
        } else {
          // Lỗi 1 trang lẻ (rate-limit / app 500) KHÔNG được giết cả lượt sync — ghi lỗi rồi chạy tiếp.
          // NHƯNG key bị chặn GIỮA CHỪNG (sau khi trang 1 đã qua) ⇒ mọi trang sau của shop cũng hỏng:
          // escalate (scope NẶNG + dừng shop) để C1 ném đỏ thay vì nuốt thành MOT_TRANG.
          if (isAuthError(err)) {
            authDeadShops.add(shopKey);
            errors.push({
              scope: "SHOP_CHET_XAC_THUC",
              stream: streamName, shop: shopKey, page, window: win || null,
              message: `BỎ QUA phần còn lại của shop "${shopKey}" — key bị chặn xác thực (401/403) giữa chừng ở trang ${page}.`,
            });
            return;
          }
          errors.push({
            scope: "MOT_TRANG",
            stream: streamName, shop: shopKey, page, window: win || null,
            message: (err && err.message) || String(err),
          });
        }
      }
      page++;
      await sleep(800); // né rate-limit Pancake (đã bị chặn key+IP 13/07 vì bắn dày)
    } while (page <= totalPages && page <= 500); // chặn vòng lặp vô hạn nếu total_pages đọc sai
  }
}

for (const st of STREAMS) {
  for (const shopKey of st.shops) {
    await pullStreamShop(st.name, shopKey, !!st.dated);
  }
}

// CHẶN NUỐT LỖI: lỗi NẶNG (mất dữ liệu — khác MOT_TRANG) phải làm workflow ĐỎ.
// Thiếu bước này thì 1 shop bị chặn api_key khiến n8n báo XANH mà doanh thu thiếu âm thầm (Pancake là nguồn duy nhất).
const nang = errors.filter((e) => e.scope !== "MOT_TRANG");
if (nang.length) {
  const nl = String.fromCharCode(10); // xuống dòng cho dễ đọc trong panel lỗi n8n
  throw new Error(
    nang.length + " lượt BỊ BỎ (mất dữ liệu):" + nl +
    nang.map((e) => "- [" + e.scope + "] " + e.stream + "/" + e.shop + ": " + e.message).join(nl)
  );
}

return [{ json: { results, errors } }];
